@app.route("/admin/mentors/<int:mentor_id>/delete", methods=["POST"])
def admin_mentor_delete(mentor_id):
    if not _logged_in():
        return redirect(url_for("admin_login", next=request.path))
    conn = db.get_conn()
    db.delete_mentor(conn, mentor_id)
    conn.close()
    return redirect(url_for("admin_list"))


@app.route("/admin/mentors/<int:mentor_id>/preview")
def admin_mentor_preview(mentor_id):
    if not _logged_in():
        return redirect(url_for("admin_login", next=request.path))
    conn = db.get_conn()
    mentor = db.get_mentor(conn, mentor_id)
    if not mentor:
        conn.close()
        abort(404)
    links = db.mentor_links(mentor)
    conn.close()
    return render_template("admin_preview.html", mentor=mentor, links=links)


